WITH kept_keys AS (SELECT id, txn_type FROM transactions INTERSECT ALL SELECT id, txn_type FROM transactions WHERE is_flagged = FALSE), reconciled AS (SELECT s.* FROM transactions s INNER JOIN kept_keys k ON s.id = k.id AND s.txn_type = k.txn_type) SELECT DATE_TRUNC('YEAR', txn_time) AS year_start, merchant, ROUND(AVG(amount), 2) AS avg_amount, MIN(txn_time) AS first_txn_time, SIZE(COLLECT_SET(merchant)) AS num_merchants, GROUPING_ID() AS grouping_level FROM reconciled GROUP BY GROUPING SETS ((DATE_TRUNC('YEAR', txn_time), merchant), (DATE_TRUNC('YEAR', txn_time)), ()) HAVING ROUND(AVG(amount), 2) > 0
